<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $thread_id = isset( $_GET['thread_id'] ) ? absint( $_GET['thread_id'] ) : 0; ?><section class="sd-inbox"><header class="sd-page-heading"><span class="sd-eyebrow"><?php esc_html_e( 'Private conversations', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'Messages', 'social-discovery' ); ?></h1><p><?php esc_html_e( 'Keep one-to-one conversations private and respectful.', 'social-discovery' ); ?></p></header><?php if ( ! sd_messages_available() ) : ?><div class="sd-empty-state"><h2><?php esc_html_e( 'Private messaging is not available yet', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'Enable BuddyPress Private Messaging to use conversations.', 'social-discovery' ); ?></p></div><?php else : ?><div class="sd-inbox-layout"><aside><?php get_template_part( 'template-parts/messaging/conversation-list' ); ?></aside><section><?php if ( $thread_id ) { get_template_part( 'template-parts/messaging/conversation', null, array( 'thread_id' => $thread_id ) ); } else { get_template_part( 'template-parts/messaging/compose-message' ); } ?></section></div><?php endif; ?></section>
